function kEsc(s){return String(s).replace(/[&<>"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c];});}
function kSlot(i){return i===undefined?document.querySelector('[data-stage]'):document.querySelector('[data-state="'+i+'"]');}
var KS=[['Seam G53 · found 2026-11-11, about 12:40 ET','A git config value that older git rejects.','Every git command failed in one shell.','Not applied: move it to the global config.','Test a config change with every git that reads the repo.'],['Withdrawn · a 5-second run','A run was called too short to file its pull request.','The branch has a commit after the logged finish.','Doubt withdrawn.','A run log records the wake, not the whole run.']];
function kitSeams(host,n){var w=document.createElement('div');w.className='seams';w.innerHTML=KS.slice(0,n).map(function(s){return '<div class="seam"><span class="seam-k">'+kEsc(s[0])+'</span><dl class="seam-rows"><dt>Break</dt><dd>'+kEsc(s[1])+'</dd><dt>Found</dt><dd>'+kEsc(s[2])+'</dd><dt>Repair</dt><dd>'+kEsc(s[3])+'</dd><dt>Guard</dt><dd>'+kEsc(s[4])+'</dd></dl></div>'}).join('');host.appendChild(w);return w}
kitSeams(kSlot(),2);
STATES.forEach(function(a,i){var b=document.createElement('div');b.style.maxWidth=a[1];kSlot(i).appendChild(b);kitSeams(b,a[0])});
